import java.util.*;

class Solution {
    public int[] removeElement(int[] nums, int val) {
        int k = 0; // next free slot for a kept element
        for (int i = 0; i < nums.length; i++) {
            if (nums[i] != val) {
                nums[k] = nums[i];
                k++;
            }
        }
        return Arrays.copyOf(nums, k); // the first k elements are the answer
    }
}

